    /// <summary>
    ///    JS-invokable method that triggers the <see cref="OnDescriptionFunction"/> function.
    ///     Should not be called by consuming code.
    /// </summary>
    [JSInvokable]
    public void OnJsDescriptionFunction()
    {
        if (IsDisposed)
        {
            // cancel if the component is disposed
            return;
        }

        if (OnDescriptionFunction is not null)
        {
            OnDescriptionFunction();
        }
    }

