    /// <summary>
    ///     Asynchronously retrieve the current value of the ActionColumn property.
    /// </summary>
    public async Task<ActionColumn?> GetActionColumn()
    {
        if (CoreJsModule is null)
        {
            return ActionColumn;
        }

        try
        {
            JsComponentReference ??= await CoreJsModule.InvokeAsync<IJSObjectReference?>(
                "getJsComponent", CancellationTokenSource.Token, Id);
        }
        catch (JSException)
        {
            // this is expected if the component is not yet built
        }

        if (JsComponentReference is null)
        {
            return ActionColumn;
        }

        // get the property value
        ActionColumn? result = await JsComponentReference.InvokeAsync<ActionColumn?>(
            "getProperty", CancellationTokenSource.Token, "actionColumn");
        if (result is not null)
